old_app='''@Composable fun RawalworldApp(){var tab by remember{mutableStateOf("home")};var service by remember{mutableStateOf<ServiceItem?>(null)};Scaffold(bottomBar={NavigationBar{NavigationBarItem(tab=="home",{tab="home";service=null},{Icon(Icons.Default.Home,null)},label={Text("Home")});NavigationBarItem(tab=="bookings",{tab="bookings"},{Icon(Icons.Default.DateRange,null)},label={Text("Bookings")});NavigationBarItem(tab=="shop",{tab="shop"},{Icon(Icons.Default.ShoppingCart,null)},label={Text("Shop")});NavigationBarItem(tab=="gallery",{tab="gallery"},{Icon(Icons.Default.Photo,null)},label={Text("Gallery")});NavigationBarItem(tab=="admin",{tab="admin"},{Icon(Icons.Default.Lock,null)},label={Text("Admin")})}}){p->Box(Modifier.fillMaxSize().padding(p)){when(tab){"service"->service?.let{ServiceScreen(it,{tab="home"},{tab="booking"})};"booking"->BookingScreen(service?.title?:"Rawalworld Service"){tab="service"};"bookings"->BookingsScreen();"shop"->ShopScreen();"gallery"->GalleryScreen();"profile"->ProfileScreen();"admin"->AdminScreen();else->HomeScreen{service=it;tab="service"}}}}}\n'''
