new_home='''@Composable fun HomeScreen(language:String,onLanguage:(String)->Unit,open:(ServiceItem)->Unit){var menu by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(14.dp).verticalScroll(rememberScrollState())){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Image(painterResource(R.drawable.rawalworld_ganeshji_final),"Ganeshji Rawalworld",Modifier.size(86.dp),contentScale=ContentScale.Fit);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("Rawalworld",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.ExtraBold);Text(tr(language,"Welcome to Rawalworld","Rawalworld માં આપનું સ્વાગત છે","Rawalworld में आपका स्वागत है","Bienvenue sur Rawalworld"))};Box{OutlinedButton(onClick={menu=true}){Text(when(language){"gu"->"ગુજરાતી";"hi"->"हिंदी";"fr"->"Français";else->"English"})};DropdownMenu(menu,onDismissRequest={menu=false}){listOf("en" to "English","gu" to "ગુજરાતી","hi" to "हिंदी","fr" to "Français").forEach{(code,label)->DropdownMenuItem(text={Text(label)},onClick={onLanguage(code);menu=false})}}}};Spacer(Modifier.height(12.dp));Card(colors=CardDefaults.cardColors(containerColor=Navy),shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(20.dp)){Text(tr(language,"Everything you need, in one app.","તમારી દરેક જરૂરિયાત, એક જ એપમાં.","आपकी हर जरूरत, एक ही ऐप में।","Tout ce dont vous avez besoin, dans une seule application."),color=Color.White,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(tr(language,"Astrology • Entertainment • Cricket • Songs • Weather • News • Maps • Booking • Flights • Trains • Shopping","જ્યોતિષ • મનોરંજન • ક્રિકેટ • ગીતો • હવામાન • સમાચાર • નકશો • બુકિંગ • ફ્લાઇટ • ટ્રેન • શોપિંગ","ज्योतिष • मनोरंजन • क्रिकेट • गाने • मौसम • समाचार • मैप • बुकिंग • फ्लाइट • ट्रेन • शॉपिंग","Astrologie • Divertissement • Cricket • Musique • Météo • Actualités • Cartes • Réservations • Vols • Trains • Shopping"),color=Color.White.copy(alpha=.88f))}};Spacer(Modifier.height(14.dp));Text(tr(language,"All Features","બધી સુવિધાઓ","सभी सुविधाएँ","Toutes les fonctions"),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);publicServices.chunked(2).forEach{pair->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){pair.forEach{s->Card(onClick={open(s)},modifier=Modifier.weight(1f).padding(vertical=5.dp),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(14.dp)){Text(s.icon,style=MaterialTheme.typography.headlineMedium);Text(serviceName(language,s.title),fontWeight=FontWeight.Bold,modifier=Modifier.padding(top=6.dp));Text(tr(language,"Tap to open","ખોલવા ટેપ કરો","खोलने के लिए टैप करें","Touchez pour ouvrir"),style=MaterialTheme.typography.bodySmall,color=Purple)}}};if(pair.size==1)Spacer(Modifier.weight(1f))}};Card(onClick={open(ServiceItem("🛍️","Online Shopping",emptyList()))},modifier=Modifier.fillMaxWidth().padding(top=8.dp),colors=CardDefaults.cardColors(containerColor=Purple),shape=RoundedCornerShape(18.dp)){Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text("🛍️",style=MaterialTheme.typography.headlineMedium);Spacer(Modifier.width(10.dp));Column{Text(serviceName(language,"Online Shopping"),color=Color.White,fontWeight=FontWeight.Bold);Text(tr(language,"Shop category-wise products","કેટેગરી પ્રમાણે પ્રોડક્ટ ખરીદો","कैटेगरी अनुसार प्रोडक्ट खरीदें","Acheter par catégorie"),color=Color.White.copy(alpha=.85f))}}};Text("📞 +91 77093 78969   ✉ rawalworld@gmail.com",Modifier.padding(top=16.dp),style=MaterialTheme.typography.bodySmall)}}'''
