new_shop='''@Composable fun ShopScreen(language:String="en"){val context=LocalContext.current;var products by remember{mutableStateOf<List<ProductRow>>(emptyList())};var loading by remember{mutableStateOf(true)};var selected by remember{mutableStateOf<ProductRow?>(null)};var category by remember{mutableStateOf("All")};LaunchedEffect(Unit){Thread{val out=mutableListOf<ProductRow>();try{val a=getArray("products?select=id,name,category,description,price,is_active,image_url&is_active=eq.true&order=created_at.desc");for(i in 0 until a.length()){val x=a.getJSONObject(i);out+=ProductRow(x.optString("id"),x.optString("name"),x.optString("category"),x.optString("description"),x.optDouble("price"),true,x.optString("image_url"))}}catch(_:Exception){};ui{products=out;loading=false}}.start()};val categories=listOf("All")+products.map{it.category}.filter{it.isNotBlank()}.distinct();val shown=if(category=="All")products else products.filter{it.category==category};Column(Modifier.fillMaxSize().padding(14.dp).verticalScroll(rememberScrollState())){Text("🛍️ ${tr(language,"Online Shopping","ઓનલાઇન શોપિંગ","ऑनलाइन शॉपिंग","Shopping en ligne")}",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text(tr(language,"Choose a category, then select your product.","કેટેગરી પસંદ કરો અને પછી પ્રોડક્ટ પસંદ કરો.","कैटेगरी चुनें और फिर प्रोडक्ट चुनें।","Choisissez une catégorie puis un produit."));Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).padding(vertical=10.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){categories.forEach{cat->if(cat==category)Button(onClick={category=cat}){Text(cat)}else OutlinedButton(onClick={category=cat}){Text(cat)}}};if(loading)CircularProgressIndicator(Modifier.padding(16.dp));if(!loading&&shown.isEmpty())Text(tr(language,"No active products found in this category.","આ કેટેગરીમાં કોઈ સક્રિય પ્રોડક્ટ નથી.","इस कैटेगरी में कोई सक्रिय प्रोडक्ट नहीं है।","Aucun produit actif dans cette catégorie."));shown.forEach{p->Card(Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(14.dp)){if(p.imageUrl.isNotBlank())RemoteImage(p.imageUrl);Text(p.name,fontWeight=FontWeight.Bold);Text(p.category,style=MaterialTheme.typography.bodySmall);if(p.description.isNotBlank())Text(p.description);Text("₹ ${String.format("%.2f",p.price)}",fontWeight=FontWeight.Bold);Button(onClick={selected=p},Modifier.fillMaxWidth().padding(top=8.dp)){Text(tr(language,"Buy Now","હમણાં ખરીદો","अभी खरीदें","Acheter"))}}}}};selected?.let{CheckoutDialog(context,it){selected=null}}}'''
